// Generates CSS variables + a typed TS module from tokens/tokens.json.
// `pnpm tokens` writes; `pnpm tokens:check` fails if generated files are stale (CI sensor).
import { readFileSync, writeFileSync } from "node:fs"
import { formatHex, parse } from "culori"

const check = process.argv.includes("--check")
const t = JSON.parse(readFileSync("tokens/tokens.json", "utf8"))
const HEADER =
  "/* AUTO-GENERATED by scripts/build-tokens.mjs from tokens/tokens.json. Do not edit. */\n"

const groups = { ...t.color, ...t.generative }
const vars = Object.entries(groups)
  .map(([k, v]) => `  --${k}: ${v};`)
  .join("\n")

// Dark only (ADR-011): one value per token, one :root block.
const css = HEADER + `:root {\n  --radius: ${t.radius};\n${vars}\n}\n`

const hex = (v) => formatHex(parse(v))
const palette = JSON.stringify(
  Object.fromEntries(Object.entries(t.generative).map(([k, v]) => [k, hex(v)])),
  null,
  2,
)

// Theme colors as hex for renderers without oklch support (OG images via next/og).
const theme = JSON.stringify(
  Object.fromEntries(Object.entries(t.color).map(([k, v]) => [k, hex(v)])),
  null,
  2,
)

const ts =
  HEADER +
  `export const generativePalette = ${palette} as const\n\nexport const themeHex = ${theme} as const\n`

const out = { "src/app/tokens.css": css, "src/lib/tokens.generated.ts": ts }
let stale = false
for (const [file, content] of Object.entries(out)) {
  if (check) {
    let cur = ""
    try {
      cur = readFileSync(file, "utf8")
    } catch {}
    if (cur !== content) {
      console.error(`✗ ${file} is stale — run \`pnpm tokens\``)
      stale = true
    }
  } else {
    writeFileSync(file, content)
    console.log(`✓ wrote ${file}`)
  }
}
if (stale) process.exit(1)
